CREATE TABLE IF NOT EXISTS personal_task_link(student_id TEXT PRIMARY KEY REFERENCES students(id) ON DELETE CASCADE,key_hash TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS personal_manual_tasks(student_id TEXT NOT NULL REFERENCES students(id) ON DELETE CASCADE,id TEXT NOT NULL CHECK(length(id) BETWEEN 1 AND 120),text TEXT NOT NULL CHECK(length(text) BETWEEN 1 AND 500),done INTEGER NOT NULL DEFAULT 0 CHECK(done IN (0,1)),version INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,deleted_at INTEGER,PRIMARY KEY(student_id,id));
CREATE TRIGGER IF NOT EXISTS personal_tasks_fence_insert BEFORE INSERT ON manual_tasks WHEN EXISTS(SELECT 1 FROM personal_task_link WHERE student_id=NEW.student_id) BEGIN SELECT RAISE(ABORT,'Tasks moved to the shared personal list'); END;
CREATE TRIGGER IF NOT EXISTS personal_tasks_fence_update BEFORE UPDATE ON manual_tasks WHEN EXISTS(SELECT 1 FROM personal_task_link WHERE student_id=NEW.student_id) BEGIN SELECT RAISE(ABORT,'Tasks moved to the shared personal list'); END;
CREATE TRIGGER IF NOT EXISTS personal_tasks_fence_delete BEFORE DELETE ON manual_tasks WHEN EXISTS(SELECT 1 FROM personal_task_link WHERE student_id=OLD.student_id) BEGIN SELECT RAISE(ABORT,'Tasks moved to the shared personal list'); END;
